import {products} from './products.js';
const $=s=>document.querySelector(s);let lang=localStorage.getItem('bridge-lang')==='ko'?'ko':'zh';
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let cart=read('bridge-cart',{}),favorites=read('bridge-favorites',[]);let query='',category='ALL',filter='all',sort='popular';
// Only item quantities are retained; delivery details never enter browser storage.
cart=Object.fromEntries(products.filter(p=>Number.isInteger(cart[p.id])&&cart[p.id]>0).map(p=>[p.id,Math.min(p.stock,cart[p.id])]).filter(([,q])=>q>0));
const tr=(zh,ko)=>lang==='zh'?zh:ko;const name=p=>p[lang];const money=(n,currency=lang==='zh'?'CNY':'KRW')=>new Intl.NumberFormat(lang==='zh'?'zh-CN':'ko-KR',{style:'currency',currency,maximumFractionDigits:0}).format(n);const price=p=>lang==='zh'?p.cny:p.krw;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'⌂',shop:'▦',orders:'▤',about:'◎',cart:'♧'};let apiAvailable=false;
fetch('./api/health').then(r=>r.ok?r.json():null).then(d=>{apiAvailable=d?.orders===true}).catch(()=>{}).finally(updateServiceStatus);
function updateServiceStatus(){const form=$('#orderForm');if(!form)return;const button=form.querySelector('button[type=submit]');button.disabled=!apiAvailable;if(!apiAvailable){$('#submitError').textContent=tr('当前为静态展示站，尚未连接申请后台，暂不接收购买申请。请使用本地服务预览申请流程。','현재 정적 데모 사이트로 신청 서버가 연결되지 않았습니다. 신청 기능은 로컬 서버에서 확인해 주세요.')}}
document.addEventListener('click',()=>queueMicrotask(updateServiceStatus));
document.addEventListener('submit',e=>{if(e.target.id==='orderForm'&&!apiAvailable){e.preventDefault();e.stopImmediatePropagation();updateServiceStatus()}},true);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function persist(){localStorage.setItem('bridge-cart',JSON.stringify(cart));$('#cartCount').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}
function route(){return location.hash.slice(1)||'home'}
function chrome(){document.documentElement.lang=lang==='zh'?'zh-CN':'ko';document.title=tr('LEGO Bridge · 连接热爱，跨越国界','LEGO Bridge · 국경을 넘어 이어지는 취미');$('#announcement').textContent=tr('连接中韩收藏市场 · 全球好物，让热爱不止于国界','중국과 한국의 컬렉터를 연결합니다 · 국경을 넘는 즐거움');const links=[['home',tr('首页','홈')],['shop',tr('商品商城','스토어')],['orders',tr('我的申请','구매 신청')],['about',tr('关于我们','소개')]];$('#nav').innerHTML=links.map(([r,n])=>`<a href="#${r}" class="${route().split('/')[0]===r?'active':''}">${n}</a>`).join('');$('#mobileNav').innerHTML=[...links.slice(0,2),['cart',tr('购物车','장바구니')],links[2]].map(([r,n])=>`<a href="#${r}" class="${route()===r?'active':''}"><span>${icons[r]}</span>${n}</a>`).join('');$('#language').textContent=lang==='zh'?'한국어':'中文';$('#cartText').textContent=tr('购物车','장바구니');$('#footer').innerHTML=`<div><a class="footer-brand" href="#home" aria-label="LEGO Bridge Home"><svg class="brand-logo" viewBox="190 260 1610 270" role="img" aria-label="LEGO Bridge"><title>LEGO Bridge</title><image href="./assets/lego-bridge-logo-a.png" width="1983" height="793" /></svg></a><br>${tr('连接全球乐高收藏市场，让限量收藏更简单。','전 세계 LEGO 수집 시장을 연결합니다.')}</div><div>${tr('创业项目演示 · 全部价格与库存为模拟数据','창업 프로젝트 데모 · 가격과 재고는 모두 예시입니다.')}<br>${tr('独立收藏服务项目，与 LEGO 集团无隶属关系。LEGO 为其权利人的商标。','LEGO 그룹과 제휴하지 않은 독립 프로젝트입니다. LEGO 상표는 해당 권리자 소유입니다.')}<br><a href="#contact">${tr('联系我们','문의')}</a> · <a href="#privacy">${tr('隐私说明','개인정보 안내')}</a> · <a href="#admin">${tr('管理入口','관리자')}</a></div>`;persist()}
const tag=p=>lang==='zh'?p.tag:({'精选收藏':'추천 컬렉션','人气之选':'인기 상품','跨境好价':'추천 가격','收藏推荐':'컬렉터 추천','入门推荐':'입문 추천','建筑美学':'건축 컬렉션'}[p.tag]||'추천');
function img(p,extra=''){return `<img src="${p.image}" alt="${esc(name(p))}" loading="lazy" ${extra}>`}
function card(p){const saving=((p.korea-p.krw)/p.korea*100).toFixed(1);return `<article class="product"><div class="product-image"><span class="badge">${tag(p)}</span><button class="heart ${favorites.includes(p.id)?'selected':''}" data-favorite="${p.id}" aria-label="${tr('收藏','찜')}" aria-pressed="${favorites.includes(p.id)}">${favorites.includes(p.id)?'♥':'♡'}</button><a href="#product/${p.id}">${img(p)}</a></div><div class="product-info"><div class="meta">${p.series} · #${p.id}</div><a href="#product/${p.id}"><h3>${esc(name(p))}</h3></a><div class="price">${money(price(p))}<small>${tr('演示价','예시 가격')}</small></div><div class="comparison"><span>${tr('韩国参考','한국 예시')} ${money(p.korea,'KRW')}</span><b>↓ ${saving}%</b></div><div class="product-bottom"><span class="${p.stock?'stock':''}">${p.stock?`● ${tr('模拟库存','예시 재고')} ${p.stock}`:tr('暂时缺货','품절')}</span><button class="add" data-add="${p.id}" aria-label="${tr('加入购物车','장바구니 담기')} ${esc(name(p))}" ${p.stock?'':'disabled'}>＋</button></div></div></article>`}
function benefits(){return `<div class="benefits">${[['⇄',tr('三地价格，一目了然','세 지역의 가격 비교'),tr('中国、韩国与国际市场参考，收藏前多一份了解。','중국·한국·글로벌 예시 가격을 한눈에 비교하세요.')],['▣',tr('跨境购买，专人确认','구매 전 개별 확인'),tr('先提交申请，再确认商品、运费和配送安排。','신청 후 상품, 배송비, 배송 일정을 확인합니다.')],['♡',tr('为收藏而连接','수집가를 위한 연결'),tr('从经典套装到设计师作品，连接每一份热爱。','클래식부터 디자이너 작품까지, 취미를 연결합니다.')]].map(([i,h,p])=>`<div class="benefit"><span>${i}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div>`}
function searchBox(){return `<form class="search" id="searchForm"><span style="color:#aaa;padding-top:9px">⌕</span><input id="searchInput" type="search" value="${esc(query)}" placeholder="${tr('搜索商品名称、系列或产品编号','상품명, 시리즈 또는 제품 번호 검색')}" aria-label="${tr('搜索商品','상품 검색')}"><button>${tr('搜索','검색')}</button></form>`}
function home(){const p=products[0];$('#app').innerHTML=`<section class="hero"><div><span class="pill"><i></i>${tr('中韩乐高收藏 · 新的连接方式','중국과 한국의 LEGO 컬렉션')}</span><h1>${tr('让收藏，<br><em>跨越国界。</em>','국경을 넘어,<br><em>수집의 즐거움.</em>')}</h1><p>${tr('连接全球乐高收藏市场。发现心仪套装，比较地区价格，让每一次收藏更有把握。','원하는 LEGO 세트를 발견하고 지역별 가격을 비교하세요. 더 현명한 수집을 위한 새로운 연결.')}</p><a href="#shop" class="primary">${tr('探索收藏','컬렉션 둘러보기')} <span>↗</span></a></div><div class="hero-art">${img(p,'fetchpriority="high"')}<div class="hero-note">${tr('本期精选 · 雄狮骑士的城堡','추천 · 사자 기사의 성')}<b>#10305 <span style="font-size:9px;color:#888">4,514 ${tr('颗粒','피스')}</span></b></div></div></section>${searchBox()}<div class="categories">${[['ALL',products[0],tr('全部套装','전체 상품')],['IDEAS',products[2],'IDEAS'],['ICONS',products[3],'ICONS'],['STAR WARS',products[5],tr('星球大战','스타워즈')],['TECHNIC',products[7],tr('机械组','테크닉')],['BOTANICALS',products[6],tr('花植系列','보태니컬')]].map(([c,p,n])=>`<button class="category" data-category="${c}">${img(p)}<span>${n}</span></button>`).join('')}</div><div class="notice"><span>◉ &nbsp; ${tr('收藏情报：中韩价格比较现已上线，发现跨境收藏的新可能。','컬렉션 소식: 중국·한국 가격 비교로 새로운 가능성을 만나세요.')}</span><a href="#about">${tr('了解更多','자세히')} →</a></div><div class="section-heading"><div><h2>${tr('精选收藏','추천 컬렉션')} <span style="color:var(--red)">.</span></h2><p>${tr('值得细细欣赏的作品，为热爱而精选','수집의 즐거움을 더해 줄 특별한 세트')}</p></div><a href="#shop">${tr('查看全部商品','전체 상품 보기')} →</a></div><div class="filters"><button class="filter active" data-home-filter="all">${tr('全部精选','전체 추천')}</button><button class="filter" data-home-filter="stock">${tr('现货优先','재고 상품')}</button><button class="filter" data-home-filter="affordable">${tr('入门收藏','입문 컬렉션')}</button><span class="muted" style="margin-left:auto;font-size:10px">${tr('价格与库存均为演示','가격·재고 모두 예시')}</span></div><div class="grid" id="homeGrid">${products.slice(0,8).map(card).join('')}</div>${benefits()}`}
function selectedProducts(){let list=products.filter(p=>(category==='ALL'||p.series===category)&&(!query||`${p.zh} ${p.ko} ${p.id} ${p.series}`.toLowerCase().includes(query.toLowerCase()))&&(filter!=='stock'||p.stock>0)&&(filter!=='favorites'||favorites.includes(p.id)));if(sort==='low')list.sort((a,b)=>price(a)-price(b));if(sort==='high')list.sort((a,b)=>price(b)-price(a));if(sort==='new')list.sort((a,b)=>b.year-a.year);return list}
function shop(){const list=selectedProducts();$('#app').innerHTML=`<div class="banner-title"><span class="eyebrow">THE COLLECTOR'S EDIT</span><h1>${tr('找到下一份心动。','다음 컬렉션을 발견하세요.')}</h1><p class="muted">${tr('从经典到创意，让每一块积木都成为故事。','클래식부터 창의적인 작품까지, 모든 브릭에 담긴 이야기.')}</p></div>${searchBox()}<div class="filters">${['ALL','IDEAS','ICONS','STAR WARS','TECHNIC','BOTANICALS','HARRY POTTER','ARCHITECTURE'].map(c=>`<button class="filter ${category===c?'active':''}" data-category="${c}">${c==='ALL'?tr('全部系列','전체 시리즈'):c}</button>`).join('')}</div><div class="filters"><button class="filter ${filter==='all'?'active':''}" data-filter="all">${tr('全部商品','전체 상품')}</button><button class="filter ${filter==='stock'?'active':''}" data-filter="stock">${tr('仅看现货','재고 상품')}</button><button class="filter ${filter==='favorites'?'active':''}" data-filter="favorites">${tr('我的收藏','찜한 상품')}</button><select id="sort" aria-label="${tr('排序','정렬')}">${[['popular',tr('默认排序','기본순')],['low',tr('价格从低到高','낮은 가격순')],['high',tr('价格从高到低','높은 가격순')],['new',tr('发行年份最新','최근 출시순')]].map(([v,n])=>`<option value="${v}" ${sort===v?'selected':''}>${n}</option>`).join('')}</select></div><p class="muted">${list.length} ${tr('款商品 · 演示库存与报价','개 상품 · 예시 재고 및 가격')}</p><div class="grid">${list.map(card).join('')}</div>${list.length?'':`<div class="empty"><h2>${tr('没有找到匹配商品','검색 결과가 없습니다')}</h2><button class="secondary" id="resetFilters">${tr('清除筛选','필터 초기화')}</button></div>`}`}
function detail(id){const p=products.find(p=>p.id===id);if(!p){$('#app').innerHTML=`<div class="empty">${tr('商品不存在','상품이 없습니다')} <a href="#shop">← ${tr('返回商城','스토어')}</a></div>`;return}const saving=((p.korea-p.krw)/p.korea*100).toFixed(1);$('#app').innerHTML=`<div class="breadcrumb"><a href="#home">${tr('首页','홈')}</a> / <a href="#shop">${tr('商品商城','스토어')}</a> / #${p.id}</div><div class="detail-top"><div class="detail-photo">${img(p)}</div><div class="detail-panel"><span class="eyebrow">${p.series} · #${p.id}</span><h1>${esc(name(p))}</h1><p class="muted">${tr('适合细细品味的搭建体验，为你的收藏架增添一段故事。','조립의 즐거움과 전시의 매력으로 컬렉션에 이야기를 더하세요.')}</p><div class="price">${money(price(p))}<small>${tr('模拟平台售价','예시 판매 가격')}</small></div><p style="color:#53997d;font-size:12px">${tr('较韩国模拟参考价低','한국 예시 가격 대비')} ${saving}%</p><div class="specs"><div><span>${tr('发行年份','출시 연도')}</span>${p.year}</div><div><span>${tr('颗粒数','피스 수')}</span>${p.pieces.toLocaleString()}</div><div><span>${tr('演示商品状态','예시 상품 상태')}</span>${tr('全新未拆封','새 제품 · 미개봉')}</div><div><span>${tr('演示库存','예시 재고')}</span>${p.stock} ${tr('件','개')}</div></div><div class="detail-actions"><button class="primary" data-add="${p.id}" ${p.stock?'':'disabled'}>${tr('加入购物车','장바구니 담기')} ＋</button><button class="secondary" data-buy="${p.id}" ${p.stock?'':'disabled'}>${tr('申请购买','구매 신청')}</button><a class="secondary" href="#contact">${tr('咨询','문의')}</a></div><p class="consent-note">${tr('提交申请后确认库存、最终报价与跨境配送费用；此处不收款。','신청 후 재고, 최종 금액, 국제 배송비를 확인합니다. 온라인 결제는 제공하지 않습니다.')}</p></div></div><section class="panel"><div class="section-heading" style="margin-top:0"><div><h2>🌍 ${tr('全球市场价格比较','글로벌 시장 가격 비교')}</h2><p>${tr('统一以韩元比较 · 人工录入模拟数据','KRW 기준 비교 · 수동 입력 예시 데이터')}</p></div><span class="muted">${p.updated}</span></div><table><thead><tr><th>${tr('市场','시장')}</th><th>${tr('参考价格（KRW）','예시 가격 (KRW)')}</th><th>${tr('数据性质','데이터 유형')}</th></tr></thead><tbody>${[[tr('中国市场','중국 시장'),Math.round(p.china*p.krw/p.cny)],[tr('韩国市场','한국 시장'),p.korea],[tr('国际市场','글로벌 시장'),p.global],[tr('LEGO Bridge 平台','LEGO Bridge'),p.krw]].map(([n,v],i)=>`<tr class="${i===3?'best':''}"><td>${n}</td><td><div class="market-price">${money(v,'KRW')} <span class="bar" style="--w:${v/p.global*150}px"></span></div></td><td>${tr('模拟报价','예시 견적')}</td></tr>`).join('')}</tbody></table><p class="consent-note">${tr('来源：创业企划演示数据，非挂牌价或成交价。中国市场栏使用本商品的固定演示换算比例，不代表实时汇率。价格不含运费、税费及服务费用；仅用于展示比较功能。','출처: 창업 기획용 예시 데이터로 실제 호가나 거래 가격이 아닙니다. 중국 가격은 상품별 고정 예시 비율로 환산하며 실시간 환율이 아닙니다. 배송비·세금·서비스 수수료는 포함되지 않습니다.')}</p></section><section class="panel"><h2>${tr('商品与购买说明','상품 및 구매 안내')}</h2><p class="muted">${tr('本页展示的是演示商品。正式交易前，管理员应提供商品实拍、包装状态与购买凭证，并与你确认库存、检查方式、配送路线、预计费用和售后约定。','데모 상품 페이지입니다. 실제 거래 전 상품 사진, 박스 상태, 구매 증빙 및 배송·검수·비용·사후 처리 조건을 개별 확인해야 합니다.')}</p><a href="${p.source}" target="_blank" rel="noopener" style="color:var(--red)">${tr('在 LEGO 官网搜索产品编号','LEGO 공식 사이트에서 제품 번호 검색')} ↗</a></section>`}
function cartPage(){const items=products.filter(p=>cart[p.id]);if(!items.length){$('#app').innerHTML=`<div class="empty"><div style="font-size:45px">♧</div><h2>${tr('下一份收藏，正在等你。','다음 컬렉션이 기다리고 있어요.')}</h2><p>${tr('购物车还是空的，先去发现喜欢的套装吧。','마음에 드는 세트를 장바구니에 담아 보세요.')}</p><a href="#shop" class="primary">${tr('探索商品','상품 둘러보기')} →</a></div>`;return}const total=items.reduce((s,p)=>s+price(p)*cart[p.id],0);$('#app').innerHTML=`<div class="banner-title"><span class="eyebrow">YOUR NEXT COLLECTION</span><h1>${tr('购物车','장바구니')}</h1><p class="muted">${tr('先申请，后确认。把跨境收藏的细节交给我们。','먼저 신청하고, 재고와 배송 조건을 확인하세요.')}</p></div><div class="cart-layout"><section class="panel" style="margin-top:0">${items.map(p=>`<div class="cart-row">${img(p)}<div><div class="meta">#${p.id}</div><h3><a href="#product/${p.id}">${esc(name(p))}</a></h3><div class="price">${money(price(p))}</div><button class="remove" data-remove="${p.id}">${tr('移除','삭제')}</button></div><div class="quantity"><button data-quantity="${p.id}" data-delta="-1" aria-label="${tr('减少数量','수량 감소')}">−</button><span>${cart[p.id]}</span><button data-quantity="${p.id}" data-delta="1" ${cart[p.id]>=p.stock?'disabled':''} aria-label="${tr('增加数量','수량 증가')}">＋</button></div></div>`).join('')}</section><section class="panel" style="margin-top:0"><h2>${tr('购买申请','구매 신청')}</h2><div class="summary-line"><span>${tr('商品模拟小计','예시 상품 소계')}</span><strong>${money(total)}</strong></div><div class="summary-line muted"><span>${tr('跨境运费 / 税费','국제 배송비 / 세금')}</span><span>${tr('待确认','확인 예정')}</span></div><hr style="border:0;border-top:1px solid #eee;margin:20px 0"><form class="form" id="orderForm"><label>${tr('姓名','이름')}<input name="customer" autocomplete="name" maxlength="80" required></label><label>${tr('联系邮箱','이메일')}<input name="email" type="email" autocomplete="email" maxlength="160" required></label><label>${tr('联系电话（选填）','연락처 (선택)')}<input name="phone" type="tel" autocomplete="tel" maxlength="40"></label><label>${tr('配送地区','배송 지역')}<select name="region"><option value="CN">${tr('中国','중국')}</option><option value="KR">${tr('韩国','한국')}</option><option value="OTHER">${tr('其他地区','기타')}</option></select></label><label>${tr('配送地址','배송 주소')}<textarea name="address" autocomplete="street-address" maxlength="500" required></textarea></label><label>${tr('备注（选填）','메모 (선택)')}<textarea name="notes" maxlength="500"></textarea></label><label class="check"><input name="consent" type="checkbox" required><span>${tr('同意使用上述信息处理本次申请，理解展示价格为模拟数据，最终价格和运费需另行确认。','신청 처리를 위한 정보 사용에 동의합니다. 표시된 가격은 예시이며 최종 금액과 배송비는 별도 확인합니다.')} <a href="#privacy" style="color:var(--red)">${tr('隐私说明','개인정보 안내')}</a></span></label><button class="primary" type="submit">${tr('提交购买申请','구매 신청 제출')} →</button><p class="consent-note">${tr('这是创业项目演示，请使用测试姓名和地址。申请不会产生付款或库存预留。','창업 프로젝트 데모입니다. 테스트 이름과 주소를 사용하세요. 신청은 결제나 재고 예약을 발생시키지 않습니다.')}</p><p id="submitError" class="error" role="alert"></p></form></section></div>`}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}
function localReceipts(){return read('bridge-receipts',[])}
function ordersPage(){const receipts=localReceipts();$('#app').innerHTML=`<div class="banner-title"><span class="eyebrow">PURCHASE REQUESTS</span><h1>${tr('我的购买申请','나의 구매 신청')}</h1><p class="muted">${tr('在此浏览器提交的申请。点击更新可查看服务器状态，不代表支付订单。','이 브라우저에서 제출한 신청입니다. 상태를 새로 확인할 수 있으며 결제 주문이 아닙니다.')}</p></div>${receipts.length?receipts.map(o=>`<article class="order-card"><span class="order-status">${statusLabel(o.status)}</span><h3>${esc(o.id)}</h3><p class="muted">${esc(new Date(o.createdAt).toLocaleString(lang==='zh'?'zh-CN':'ko-KR'))} · ${money(o.total,o.currency)}</p><p>${o.items.map(i=>`${esc(name(products.find(p=>p.id===i.id))||i.id)} × ${i.quantity}`).join(' / ')}</p><button class="secondary" data-refresh-order="${esc(o.id)}">${tr('更新状态','상태 확인')}</button></article>`).join(''):`<div class="empty"><h2>${tr('还没有购买申请','아직 신청 내역이 없습니다')}</h2><a href="#shop" class="primary">${tr('前往商城','스토어로 이동')}</a></div>`}`}
function statusLabel(s){return ({pending:tr('待人工确认','확인 대기'),contacted:tr('已联系','연락 완료'),confirmed:tr('已确认','확인 완료'),closed:tr('已关闭','종료')})[s]||s}
function infoPage(which){const data={about:[tr('让热爱，不止于国界。','국경을 넘어 이어지는 즐거움.'),tr('LEGO Bridge 是一个面向中韩收藏者的创业项目，探索乐高收藏品展示、地区参考价格比较和跨境购买服务。','LEGO Bridge는 중국과 한국의 수집가를 위한 창업 프로젝트입니다. LEGO 컬렉션, 지역별 가격 비교, 해외 구매 서비스를 연결합니다.'),tr('我们相信，收藏不仅是拥有，更是发现、搭建与分享。第一版以精选套装和透明的价格信息为起点，通过人工确认，逐步完善商品检查与物流服务。','수집은 소유를 넘어 발견하고 조립하고 나누는 과정입니다. 추천 세트와 투명한 가격 정보를 시작으로, 개별 확인을 통해 검수와 배송 서비스를 발전시킵니다.')],contact:[tr('每一份收藏，都值得认真对待。','모든 컬렉션을 소중하게.'),tr('需要寻找特定套装，或咨询跨境配送？可以先提交购买申请并填写邮箱，我们将在后台查看。','특정 세트 또는 국제 배송에 대해 궁금하신가요? 구매 신청에 이메일을 남겨 주세요.'),tr('客服邮箱与聊天软件账号尚未配置。当前为项目演示，没有对外客服渠道或承诺响应时间。请使用测试信息提交申请。','고객센터 이메일과 채팅 계정은 아직 설정되지 않았습니다. 현재 데모이며 외부 상담 채널이나 응답 시간 보장은 없습니다. 테스트 정보로 신청해 주세요.')],privacy:[tr('隐私与演示说明','개인정보 및 데모 안내'),tr('购物车、收藏、语言选择和申请查询凭据保存在当前浏览器。姓名、邮箱、电话和地址通过申请接口保存到服务器的私有数据目录，不会写入公开 GitHub 仓库。申请数据仅供管理员处理本次联系与报价，当前演示请勿填写真实个人信息。','장바구니, 찜, 언어, 신청 조회 키는 현재 브라우저에 저장됩니다. 이름, 이메일, 전화번호, 주소는 서버의 비공개 데이터 폴더에 저장되며 공개 GitHub 저장소에 포함되지 않습니다. 신청 처리 및 연락에만 사용되며 데모에는 실제 개인정보를 입력하지 마세요.'),tr('商品价格、库存与价格比较全部是模拟数据，无实时汇率或投资承诺。商品图通过 Brickset 外部图片地址展示，第三方会接收常规网络请求。正式运营前须配置运营者联系方式、数据保留和删除政策、真实商品资料及安全托管。','가격·재고·비교는 모두 예시이며 실시간 환율이나 투자 약속이 아닙니다. 상품 사진은 Brickset의 외부 주소로 표시되며 제3자에게 일반적인 웹 요청이 전달됩니다. 실제 운영 전 운영자 연락처, 보관·삭제 정책, 실제 상품 정보, 안전한 호스팅을 준비해야 합니다.')]};const [title,a,b]=data[which];$('#app').innerHTML=`<section class="intro panel"><span class="eyebrow">LEGO BRIDGE</span><h1>${title}</h1><p>${a}</p><p>${b}</p><a class="primary" href="#shop">${tr('探索商品','상품 둘러보기')} →</a>${which==='about'?benefits():''}</section>`}
function adminPage(){ $('#app').innerHTML=`<section class="panel intro"><span class="eyebrow">ADMINISTRATION</span><h1>${tr('申请管理','신청 관리')}</h1><p class="muted">${tr('输入服务器配置的管理员密钥查看申请。密钥不会保存在浏览器。未配置密钥时管理接口关闭。','서버 관리자 키로 신청을 확인하세요. 키는 브라우저에 저장하지 않으며 미설정 시 관리 기능이 닫힙니다.')}</p><form class="form" id="adminForm"><label>${tr('管理员密钥','관리자 키')}<input name="token" type="password" required autocomplete="off"></label><button class="primary">${tr('读取申请','신청 조회')}</button></form><div id="adminResults"></div></section>`}
let adminToken='';
function render(){adminToken='';chrome();const [page,id]=route().split('/');if(page==='home')home();else if(page==='shop')shop();else if(page==='product')detail(id);else if(page==='cart')cartPage();else if(page==='orders')ordersPage();else if(['about','contact','privacy'].includes(page))infoPage(page);else if(page==='admin')adminPage();else{$('#app').innerHTML=`<div class="empty">${tr('页面不存在','페이지를 찾을 수 없습니다')} <a href="#home">${tr('返回首页','홈')}</a></div>`}imageFallbacks();updateServiceStatus()}
function imageFallbacks(){document.querySelectorAll('img').forEach(i=>{i.onerror=()=>{i.alt=tr('商品图片暂不可用 · 产品编号见下方','상품 이미지 준비 중 · 제품 번호를 확인하세요');i.style.fontSize='10px';i.style.color='#aaa';i.style.padding='15px'}})}
function add(id,notify=true){const p=products.find(p=>p.id===id);if(!p?.stock)return false;if((cart[id]||0)>=p.stock){toast(tr('已达到演示库存上限','예시 재고 한도에 도달했습니다'));return false}cart[id]=(cart[id]||0)+1;persist();if(notify)toast(tr('已加入购物车','장바구니에 담았습니다'));return true}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add)add(b.dataset.add);if(b.dataset.buy){if(!cart[b.dataset.buy])add(b.dataset.buy,false);location.hash='cart'}if(b.dataset.favorite){const id=b.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];localStorage.setItem('bridge-favorites',JSON.stringify(favorites));b.textContent=favorites.includes(id)?'♥':'♡';b.classList.toggle('selected',favorites.includes(id));b.setAttribute('aria-pressed',String(favorites.includes(id)));if(route()==='shop'&&filter==='favorites')shop()}if(b.dataset.category){category=b.dataset.category;filter='all';if(route()==='shop')shop();else location.hash='shop';imageFallbacks()}if(b.dataset.filter){filter=b.dataset.filter;shop();imageFallbacks()}if(b.dataset.homeFilter){document.querySelectorAll('[data-home-filter]').forEach(x=>x.classList.toggle('active',x===b));$('#homeGrid').innerHTML=products.filter(p=>b.dataset.homeFilter==='stock'?p.stock>0:b.dataset.homeFilter==='affordable'?p.cny<1300:true).slice(0,8).map(card).join('');imageFallbacks()}if(b.id==='resetFilters'){query='';category='ALL';filter='all';sort='popular';shop();imageFallbacks()}if(b.dataset.remove){delete cart[b.dataset.remove];persist();cartPage();imageFallbacks()}if(b.dataset.quantity){const id=b.dataset.quantity;const q=cart[id]+Number(b.dataset.delta);if(q<1)delete cart[id];else if(q<=products.find(p=>p.id===id).stock)cart[id]=q;persist();cartPage();imageFallbacks()}if(b.dataset.refreshOrder){const receipts=localReceipts(),o=receipts.find(x=>x.id===b.dataset.refreshOrder);try{b.disabled=true;const r=await fetch(`./api/orders/${encodeURIComponent(o.id)}`,{headers:{'X-Order-Key':o.key}});if(!r.ok)throw Error();const d=await r.json();o.status=d.status;localStorage.setItem('bridge-receipts',JSON.stringify(receipts));ordersPage();toast(tr('状态已更新','상태를 확인했습니다'))}catch{toast(tr('暂时无法查询，请确认服务器在线','서버 연결을 확인해 주세요'));b.disabled=false}}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;shop();imageFallbacks()}if(e.target.dataset.orderStatus)updateStatus(e.target)});
document.addEventListener('submit',async e=>{if(e.target.id==='searchForm'){e.preventDefault();query=$('#searchInput').value.trim();if(route()==='shop'){shop();imageFallbacks()}else location.hash='shop'}if(e.target.id==='orderForm'){e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');button.disabled=true;$('#submitError').textContent='';try{const data=Object.fromEntries(new FormData(form));const items=Object.entries(cart).map(([id,quantity])=>({id,quantity}));const r=await fetch('./api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,items,currency:lang==='zh'?'CNY':'KRW',locale:lang})});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||tr('申请服务未连接，未提交任何信息。','신청 서버에 연결되지 않아 제출되지 않았습니다.'));const receipts=localReceipts();receipts.unshift({...d,items});localStorage.setItem('bridge-receipts',JSON.stringify(receipts));cart={};persist();location.hash='orders';modal(`<span class="eyebrow">REQUEST RECEIVED</span><h2>${tr('购买申请已收到','구매 신청이 접수되었습니다')}</h2><p>${esc(d.id)}</p><p class="muted">${tr('申请已保存到服务器，等待管理员确认。这不是付款订单，也没有预留库存。请保留当前浏览器中的查询凭据。','서버에 저장되었으며 관리자 확인을 기다립니다. 결제 주문이나 재고 예약이 아닙니다. 이 브라우저의 조회 키를 보관하세요.')}</p>`)}catch(err){$('#submitError').textContent=err.message;button.disabled=false}}if(e.target.id==='adminForm'){e.preventDefault();adminToken=new FormData(e.target).get('token');e.target.reset();await loadAdmin()}});
async function loadAdmin(){try{const r=await fetch('./api/admin/orders',{headers:{Authorization:`Bearer ${adminToken}`}});const d=await r.json();if(!r.ok)throw Error(tr('密钥不正确，或管理服务未开启。','키가 올바르지 않거나 관리 서비스가 꺼져 있습니다.'));$('#adminResults').innerHTML=`<p class="muted">${d.length} ${tr('条申请','건의 신청')}</p>`+d.map(o=>`<article class="admin-order"><b>${esc(o.id)}</b><p>${esc(o.customer)} · ${esc(o.email)} · ${esc(o.phone)}</p><p>${esc(o.region)} · ${esc(o.address)}</p><p>${o.items.map(i=>`#${esc(i.id)} × ${i.quantity}`).join(' / ')} · ${money(o.total,o.currency)}</p><p>${esc(o.notes)}</p><select data-order-status="${esc(o.id)}">${['pending','contacted','confirmed','closed'].map(s=>`<option value="${s}" ${o.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select><button class="text-button" data-delete-order="${esc(o.id)}">${tr('删除测试申请','테스트 신청 삭제')}</button></article>`).join('')}catch(e){$('#adminResults').textContent=e.message}}
async function updateStatus(select){try{select.disabled=true;const r=await fetch(`./api/admin/orders/${encodeURIComponent(select.dataset.orderStatus)}`,{method:'PATCH',headers:{Authorization:`Bearer ${adminToken}`,'Content-Type':'application/json'},body:JSON.stringify({status:select.value})});if(!r.ok)throw Error();toast(tr('状态已保存','상태가 저장되었습니다'))}catch{toast(tr('保存失败，请重新读取申请','저장 실패. 신청을 다시 조회하세요'));await loadAdmin()}finally{select.disabled=false}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-delete-order]');if(!b)return;modal(`<h2>${tr('删除这条测试申请？','테스트 신청을 삭제할까요?')}</h2><p class="muted">${tr('将从服务器永久移除申请中的联系与地址信息。','서버에서 신청과 연락처·주소를 영구 삭제합니다.')}</p><button class="primary" id="confirmDelete">${tr('确认删除','삭제 확인')}</button>`);$('#confirmDelete').onclick=async()=>{const r=await fetch(`./api/admin/orders/${encodeURIComponent(b.dataset.deleteOrder)}`,{method:'DELETE',headers:{Authorization:`Bearer ${adminToken}`}});$('#modal').close();toast(r.ok?tr('已删除','삭제 완료'):tr('删除失败','삭제 실패'));await loadAdmin()}});
$('#language').onclick=()=>{lang=lang==='zh'?'ko':'zh';localStorage.setItem('bridge-lang',lang);render()};$('#cartButton').onclick=()=>location.hash='cart';$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
